package com.collectiq.web;
import com.collectiq.domain.*;import com.collectiq.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.math.BigDecimal;import java.time.LocalDate;import java.time.temporal.ChronoUnit;import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="http://localhost:3000") public class ApiController{
 private final CustomerRepository cr;private final InvoiceRepository ir;private final RestClient agent=RestClient.create();public ApiController(CustomerRepository c,InvoiceRepository i){cr=c;ir=i;seed();}
 private void seed(){if(cr.count()>0)return;Customer a=new Customer();a.name="Sharma Distributors";a.email="accounts@sharma.example";a.phone="+919900000001";cr.save(a);Customer b=new Customer();b.name="Metro Retail";b.email="finance@metro.example";cr.save(b);for(int n=1;n<=6;n++){Invoice x=new Invoice();x.customer=n%2==0?b:a;x.invoiceNumber="INV-2026-"+String.format("%03d",n);x.amount=BigDecimal.valueOf(n*18500L);x.dueDate=LocalDate.now().minusDays(n*4L);x.status=n==6?"PAID":"OPEN";ir.save(x);}}
 @GetMapping("/customers")public List<Map<String,Object>> customers(){return cr.findByTenantId("demo").stream().map(c->Map.<String,Object>of("id",c.id,"name",c.name,"email",Objects.toString(c.email,""),"phone",Objects.toString(c.phone,""))).toList();}
 @PostMapping("/customers")public Customer addCustomer(@RequestBody Customer c){c.id=null;c.tenantId="demo";return cr.save(c);}
 @GetMapping("/invoices")public List<Map<String,Object>> invoices(){return ir.findByTenantIdOrderByDueDateAsc("demo").stream().map(this::view).toList();}
 private Map<String,Object> view(Invoice i){return Map.of("id",i.id,"invoiceNumber",i.invoiceNumber,"customerName",i.customer.name,"amount",i.amount,"dueDate",i.dueDate.toString(),"status",i.status);}
 @PostMapping("/invoices")public Map<String,Object> addInvoice(@RequestBody Map<String,Object>b){Invoice i=new Invoice();i.invoiceNumber=b.get("invoiceNumber").toString();i.amount=new BigDecimal(b.get("amount").toString());i.dueDate=LocalDate.parse(b.get("dueDate").toString());i.customer=cr.findById(Long.valueOf(b.get("customerId").toString())).orElseThrow();return view(ir.save(i));}
 @GetMapping("/dashboard")public Map<String,Object> dashboard(){var all=ir.findByTenantIdOrderByDueDateAsc("demo");BigDecimal out=all.stream().filter(i->!i.status.equals("PAID")).map(i->i.amount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal overdue=all.stream().filter(i->!i.status.equals("PAID")&&i.dueDate.isBefore(LocalDate.now())).map(i->i.amount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("outstanding",out,"overdue",overdue,"overdueCount",all.stream().filter(i->!i.status.equals("PAID")&&i.dueDate.isBefore(LocalDate.now())).count(),"collectedThisMonth",BigDecimal.ZERO);}
 @PostMapping("/invoices/{id}/draft-reminder")public Map<String,Object> draft(@PathVariable Long id){Invoice i=ir.findById(id).orElseThrow();var body=Map.of("customer_name",i.customer.name,"invoice_number",i.invoiceNumber,"amount",i.amount.toString(),"due_date",i.dueDate.toString(),"days_overdue",Math.max(0,ChronoUnit.DAYS.between(i.dueDate,LocalDate.now())));try{return agent.post().uri("http://agent:8000/draft").body(body).retrieve().body(Map.class);}catch(Exception e){String msg="Hi "+i.customer.name+", friendly reminder for invoice "+i.invoiceNumber+" of ₹"+i.amount+" due "+i.dueDate+". Please share expected payment date. Thank you.";return Map.of("draft",msg,"message",msg,"requiresApproval",true);}}
}